INSERT INTO `landing_page_content` (`id`, `section_key`, `section_title`, `section_subtitle`, `section_content`, `section_image`, `section_order`, `is_active`, `extra_data`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'Prospecção B2B com Google Maps, LinkedIn e dados de CNPJ', 'Planeje buscas por segmento e localidade, acompanhe leads e organize o trabalho comercial em um único painel.', '<p>O MapsProspector reúne recursos de prospecção para pesquisar empresas, consultar dados cadastrais quando a fonte configurada os disponibilizar e organizar a rotina da equipe. A disponibilidade e o retorno de cada pesquisa dependem da fonte conectada, dos filtros usados e das regras aplicáveis.</p>', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiTTm24MTRaN_QuPcGyiHRdf2lcveS9myS6CJKzMH0jHLbSTs9DyWmaVCaolVmknZuPLhs_N9mm4jdUsQNJlGDXnyIt0U4TqxQ5YncjwKm28zjQ6PfcenaFX9sDfQ2E-8s0vr7Gbpu_rmLUncU99WG4vsUoUuvGKme-NKhTPm10w_VXS31o3DBP-d1qy3Q/s1901/Captura%20de%20tela%202026-07-18%20111641.png', 1, 1, '{\"cta_link\": \"#register\", \"cta_text\": \"Criar acesso gratuito\", \"video_url\": null}', '2026-07-07 16:56:01', '2026-08-21 11:51:26'),
(2, 'features', 'Recursos para organizar a prospecção', 'Conheça as funções disponíveis e escolha a forma de pesquisa adequada ao seu processo comercial.', NULL, '', 2, 1, '{\"items\": [{\"icon\": \"search\", \"title\": \"Prospecção no Google Maps\", \"description\": \"Pesquise empresas por segmento e localidade e trabalhe os resultados retornados pela fonte configurada.\"}, {\"icon\": \"users\", \"title\": \"Pesquisa no LinkedIn\", \"description\": \"Consulte perfis por cargo e localidade quando a sessão autenticada estiver disponível e autorizada.\"}, {\"icon\": \"shield\", \"title\": \"Consulta de CNPJ\", \"description\": \"Visualize atributos cadastrais e contatos que a fonte de dados configurada retornar para a empresa pesquisada.\"}, {\"icon\": \"chart\", \"title\": \"Organização de leads\", \"description\": \"Acompanhe resultados, histórico e dados de trabalho em um painel compartilhado conforme as permissões da equipe.\"}, {\"icon\": \"clock\", \"title\": \"Planos e créditos\", \"description\": \"Acompanhe os recursos do plano e os créditos aplicáveis às buscas contratadas.\"}]}', '2026-07-07 16:56:01', '2026-08-21 11:51:26'),
(3, 'how_it_works', 'Como começar a prospectar', 'Um fluxo simples para transformar critérios comerciais em uma lista de trabalho.', '<ol class=\"space-y-4\"><li class=\"flex items-start gap-4\"><span class=\"flex-shrink-0 w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold\">1</span><div><strong>Defina seu recorte</strong><p class=\"text-slate-600\">Escolha segmento, localidade e demais critérios coerentes com o público que deseja trabalhar.</p></div></li><li class=\"flex items-start gap-4\"><span class=\"flex-shrink-0 w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold\">2</span><div><strong>Inicie a pesquisa disponível</strong><p class=\"text-slate-600\">Use Google Maps, LinkedIn autenticado ou consulta de CNPJ conforme a finalidade e a disponibilidade de cada fonte.</p></div></li><li class=\"flex items-start gap-4\"><span class=\"flex-shrink-0 w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold\">3</span><div><strong>Revise e organize os resultados</strong><p class=\"text-slate-600\">Avalie os dados retornados, registre o andamento e distribua o trabalho para a equipe quando necessário.</p></div></li></ol>', '', 3, 1, NULL, '2026-07-07 16:56:01', '2026-08-21 11:51:26'),
(4, 'benefits', 'Um painel para o processo comercial', 'Funções para apoiar a pesquisa, a organização e o acompanhamento de leads.', NULL, NULL, 4, 1, '{\"items\": [{\"icon\": \"clock\", \"title\": \"Critérios de pesquisa\", \"description\": \"Organize pesquisas por segmento, localização e outros filtros disponíveis em cada fonte.\"}, {\"icon\": \"check-circle\", \"title\": \"Consulta orientada por fonte\", \"description\": \"Identifique de qual recurso veio cada retorno e revise os dados antes de utilizá-los comercialmente.\"}, {\"icon\": \"trending-up\", \"title\": \"Histórico de trabalho\", \"description\": \"Mantenha o acompanhamento de pesquisas e leads dentro do ambiente da empresa.\"}, {\"icon\": \"users\", \"title\": \"Equipe com permissões\", \"description\": \"Estruture os acessos conforme o papel de cada integrante e a política da organização.\"}]}', '2026-07-07 16:56:01', '2026-08-21 11:51:26'),
(5, 'testimonials', 'O Que Nossos Clientes Dizem', 'Veja o que empreended ores estão conseguindo com o MapsProspector', NULL, NULL, 5, 0, '{\"items\": []}', '2026-07-07 16:56:01', '2026-08-21 10:30:35'),
(6, 'faq', 'Perguntas frequentes', 'Informações para entender os recursos e os limites de uso da plataforma.', NULL, NULL, 6, 1, '{\"items\": [{\"answer\": \"A plataforma disponibiliza recursos para Google Maps, LinkedIn autenticado e consulta de CNPJ. O retorno depende da configuração, disponibilidade da fonte e dos filtros aplicados.\", \"question\": \"Quais fontes de pesquisa estão disponíveis?\"}, {\"answer\": \"O cancelamento pode ser solicitado pelo painel. Quando houver período já pago, o acesso permanece até o seu encerramento, sem estorno automático.\", \"question\": \"Posso cancelar uma assinatura mensal?\"}, {\"answer\": \"A tela apresenta os campos que a fonte de dados configurada retornar. Alguns atributos podem não estar disponíveis para todos os CNPJs consultados.\", \"question\": \"Os dados de CNPJ sempre incluem contatos e quadro societário?\"}, {\"answer\": \"Os créditos e limites são definidos pelo plano e pelas regras da função utilizada. Consulte os detalhes do plano antes de iniciar pesquisas em volume.\", \"question\": \"Como funcionam os créditos de busca?\"}]}', '2026-07-07 16:56:01', '2026-08-21 11:51:26'),
(7, 'cta', 'Conheça os recursos do MapsProspector', 'Explore as soluções, consulte os planos disponíveis e crie seu acesso quando estiver pronto.', '<p>Veja como cada recurso funciona e escolha os fluxos compatíveis com a rotina comercial da sua empresa.</p>', NULL, 7, 1, '{\"cta_link\": \"index.php?register=1\", \"cta_text\": \"Criar acesso gratuito\", \"secondary_cta_link\": \"solucoes.php\", \"secondary_cta_text\": \"Ver soluções\"}', '2026-07-07 16:56:01', '2026-08-21 11:51:26'),
(8, 'footer', '', '', '<p>&copy; 2026 MapsProspector. Todos os direitos reservados.</p>', '', 8, 1, '{\"company_name\": \"MapsProspector\", \"social_links\": {\"email\": \"contato@atendo.log.br\", \"whatsapp\": \"551731981705\"}}', '2026-07-07 16:56:01', '2026-08-21 11:51:26');
INSERT INTO `landing_page_content_backup_20260821` (`id`, `section_key`, `section_title`, `section_subtitle`, `section_content`, `section_image`, `section_order`, `is_active`, `extra_data`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'A plataforma de Prospecção B2B mais completa do mercado', 'Localize empresas no Maps, enriqueça com dados do CNPJ e gerencie sua equipe de vendas em um só lugar.', '<p>Descubra empresas próximas ao seu negócio com dados precisos e atualizados. Nossa ferramenta a busca automaticamente enquanto você foca em vender.</p>', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiTTm24MTRaN_QuPcGyiHRdf2lcveS9myS6CJKzMH0jHLbSTs9DyWmaVCaolVmknZuPLhs_N9mm4jdUsQNJlGDXnyIt0U4TqxQ5YncjwKm28zjQ6PfcenaFX9sDfQ2E-8s0vr7Gbpu_rmLUncU99WG4vsUoUuvGKme-NKhTPm10w_VXS31o3DBP-d1qy3Q/s1901/Captura%20de%20tela%202026-07-18%20111641.png', 1, 1, '{\"cta_link\": \"#register\", \"cta_text\": \"Começar agora grátis\", \"video_url\": null}', '2026-07-07 16:56:01', '2026-07-18 14:21:10'),
(2, 'features', 'Recursos Potentes', 'Tudo que você precisa para prospectar clientes', '', '', 2, 1, '{\"items\": [{\"icon\": \"search\", \"title\": \"Prospecção no Maps\", \"description\": \"Localize milhares de empresas em tempo real usando o poder de busca do Google Maps com filtros por ramo e cidade.\"}, {\"icon\": \"shield\", \"title\": \"Consulta CNPJ Premium\", \"description\": \"Enriqueça seus leads com dados oficiais da Receita Federal: Sócios, Capital Social, CNAEs e Situação Cadastral.\"}, {\"icon\": \"users\", \"title\": \"Gestão de Equipe\", \"description\": \"Cadastre seus vendedores e SDRs para prospectarem juntos, compartilhando o saldo de créditosde forma organizada.\"}, {\"icon\": \"chart\", \"title\": \"Exportação Direta\", \"description\": \"Envie seus leads enriquecidos instantaneamente para seu CRM via Webhook ou exporte para Excel de forma simplificada.\"}, {\"icon\": \"headphones\", \"title\": \"Alertas via WhatsApp\", \"description\": \"Receba notificações de novos pedidos, aprovações e avisos de saldo baixo diretamente no seu celular.\"}]}', '2026-07-07 16:56:01', '2026-07-18 12:18:10'),
(3, 'how_it_works', 'Como Funciona', 'Três passos simples para encontrar seus clientes', '<ol class=\"space-y-4\"><li class=\"flex items-start gap-4\"><span class=\"flex-shrink-0 w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold\">1</span><div><strong>Defina seu público</strong><p class=\"text-slate-600\">Escolha o segmento, região e critérios de busca</p></div></li><li class=\"flex items-start gap-4\"><span class=\"flex-shrink-0 w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold\">2</span><div><strong>Deixe nosso sistema trabalhar</strong><p class=\"text-slate-600\">Nossa ferramenta busca automaticamente no Google Maps</p></div></li><li class=\"flex items-start gap-4\"><span class=\"flex-shrink-0 w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold\">3</span><div><strong>Converta clientes</strong><p class=\"text-slate-600\">Exporte os dados para seu CRM e comece a vender</p></div></li></ol>', '', 3, 1, NULL, '2026-07-07 16:56:01', '2026-07-13 15:13:24'),
(4, 'benefits', 'Por Que Escolher o MapsProspector?', 'A solução completa para sua prospecção B2B', NULL, NULL, 4, 1, '{\"items\": [{\"icon\": \"clock\", \"title\": \"Economize Tempo\", \"description\": \"Automatize a busca de leads e focando apenas no que importa: vender\"}, {\"icon\": \"check-circle\", \"title\": \"Dados Precisos\", \"description\": \"Informações direto do Google Maps, sempre atualizadas e confiáveis\"}, {\"icon\": \"trending-up\", \"title\": \"Escalável\", \"description\": \"Planos que crescem com seu negócio, desde pequenas empresas até grandes corporações\"}, {\"icon\": \"headphones\", \"title\": \"Suporte Dedicado\", \"description\": \"Nossa equipe está sempre pronta para ajudar você a atingir seus objetivos\"}]}', '2026-07-07 16:56:01', '2026-07-07 16:56:01'),
(5, 'testimonials', 'O Que Nossos Clientes Dizem', 'Veja o que empreended ores estão conseguindo com o MapsProspector', NULL, NULL, 5, 0, '{\"items\": []}', '2026-07-07 16:56:01', '2026-08-21 10:30:35'),
(6, 'faq', 'Perguntas Frequentes', 'Tire suas dúvidas sobre o MapsProspector', NULL, NULL, 6, 1, '{\"items\": [{\"answer\": \"Oferecemos 7 dias gratuitos para você testar todas as funcionalidades. Não precisa de cartão de crédito.\", \"question\": \"Como funciona o período de teste?\"}, {\"answer\": \"Sim! Cancelamento sem burocracias. Você mantém acesso até o final do período pago.\", \"question\": \"Posso cancelar a qualquer momento?\"}, {\"answer\": \"Sim, buscamos diretamente do Google Maps e atualizamos conforme você solicita novas buscas.\", \"question\": \"Os dados são atualizados?\"}, {\"answer\": \"Claro! Exportamos para Excel, CSV ou/enviamos automaticamente via webhook para seu CRM.\", \"question\": \"Posso exportar para meu CRM?\"}]}', '2026-07-07 16:56:01', '2026-07-07 16:56:01'),
(7, 'cta', 'Pronto para Transformar sua Prospecção?', 'Comece hoje mesmo e conquiste mais clientes', '<p>Junte-se a milhares de empreended ores que já estão crescendo seus negócios com o MapsProspector.</p>', NULL, 7, 1, '{\"cta_link\": \"#register\", \"cta_text\": \"Cadastrar Minha Empresa Grátis\", \"secondary_cta_link\": \"#contact\", \"secondary_cta_text\": \"Falar com Consultor\"}', '2026-07-07 16:56:01', '2026-07-07 16:56:01'),
(8, 'footer', '', '', '<p>© 2025 - 2026 MapsProspector. Todos os direitos reservados.</p>', '', 8, 1, '{\"company_name\": \"MapsProspector\", \"social_links\": {\"email\": \"contato@atendo.log.br\", \"whatsapp\": \"551731981705\"}}', '2026-07-07 16:56:01', '2026-07-18 12:18:55');
INSERT INTO `landing_page_sections` (`id`, `section_key`, `section_title`, `section_subtitle`, `section_content`, `extra_data`, `updated_at`) VALUES
(1, 'hero', 'Prospecção comercial com mais clareza', 'Encontre empresas, organize oportunidades e transforme buscas em ações comerciais.', '<p>Centralize suas pesquisas de mercado em uma experiência simples para sua equipe, com histórico e próximos passos no mesmo fluxo.</p>', '{\"cta_text\": \"Começar agora\"}', '2026-08-14 02:03:09'),
(2, 'features', 'Ferramentas para sua rotina comercial', 'Uma base organizada para pesquisar, consultar e acompanhar seus próximos contatos.', NULL, '{\"items\": [{\"icon\": \"map\", \"title\": \"Pesquisa no Maps\", \"description\": \"Encontre empresas por categoria e localização.\"}, {\"icon\": \"search\", \"title\": \"Pesquisa LinkedIn\", \"description\": \"Organize buscas por cargo, localidade e empresa.\"}, {\"icon\": \"chart\", \"title\": \"Acompanhamento\", \"description\": \"Consulte seu histórico e mantenha o trabalho comercial organizado.\"}, {\"icon\": \"check-circle\", \"title\": \"Consulta de CNPJ\", \"description\": \"Consulte dados cadastrais por CNPJ, sem confundir a busca com razão social.\"}]}', '2026-08-14 02:03:09'),
(3, 'how_it_works', 'Como funciona', 'Comece com uma busca objetiva e avance com os dados que fazem sentido para sua equipe.', '<p>Escolha o tipo de pesquisa, informe os critérios e analise os resultados antes de iniciar o contato.</p>', '{\"steps\": [{\"title\": \"Escolha a pesquisa\", \"number\": \"01\", \"description\": \"Selecione Maps, LinkedIn ou consulta de CNPJ conforme o objetivo comercial.\"}, {\"title\": \"Defina os critérios\", \"number\": \"02\", \"description\": \"Informe localização, categoria, cargo ou CNPJ com o máximo de clareza.\"}, {\"title\": \"Revise e avance\", \"number\": \"03\", \"description\": \"Analise os dados retornados, consulte o histórico e organize a próxima ação.\"}]}', '2026-08-14 02:03:09'),
(4, 'benefits', 'Mais foco para sua prospecção', 'Reduza tarefas dispersas e mantenha as informações importantes em um só lugar.', NULL, '{\"items\": [{\"icon\": \"clock\", \"title\": \"Mais agilidade\", \"description\": \"Encontre informações essenciais com menos etapas.\"}, {\"icon\": \"shield\", \"title\": \"Uso responsável\", \"description\": \"Consulte os dados de acordo com as regras e os termos aplicáveis.\"}, {\"icon\": \"check-circle\", \"title\": \"Fluxo organizado\", \"description\": \"Retome suas pesquisas pelo histórico sempre que precisar.\"}, {\"icon\": \"users\", \"title\": \"Equipe alinhada\", \"description\": \"Dê visibilidade aos critérios e às pesquisas que orientam o trabalho comercial.\"}]}', '2026-08-14 02:03:09'),
(5, 'faq', 'Dúvidas frequentes', 'Veja os pontos principais antes de iniciar.', NULL, '{\"items\": [{\"answer\": \"Sim. O acesso às ferramentas depende de uma conta ativa.\", \"question\": \"Preciso criar uma conta para utilizar o sistema?\"}, {\"answer\": \"Sim. As pesquisas salvas ficam disponíveis no histórico da conta conforme as regras configuradas para o seu acesso.\", \"question\": \"Posso consultar pesquisas anteriores?\"}, {\"answer\": \"Não. A empresa é opcional; cargo e localização são os critérios obrigatórios.\", \"question\": \"A pesquisa LinkedIn exige uma empresa?\"}, {\"answer\": \"Não. Nesta versão, a ferramenta realiza consulta cadastral por CNPJ.\", \"question\": \"A consulta de CNPJ busca razão social?\"}]}', '2026-08-14 02:03:09'),
(6, 'cta', 'Pronto para organizar sua prospecção?', 'Entre na sua conta ou conheça o fluxo de cadastro.', '<p>Comece com uma pesquisa e avance no seu ritmo.</p>', '{\"cta_text\": \"Entrar\", \"secondary_cta_text\": \"Criar conta\"}', '2026-08-14 02:03:09'),
(7, 'footer', NULL, NULL, '<p>Maps Prospector — prospecção comercial organizada.</p>', NULL, '2026-08-14 02:03:09');
